const dm2_v1_dos_file_fp_t *dm2_v1_dos_file_fp_lookup_pc34(const char *name) {
    if (!name) return NULL;
    for (int i = 0; i < DM2_V1_DOS_FILE_COUNT; ++i) {
        if (strcmp(dm2_v1_dos_files[i].name, name) == 0)
            return &dm2_v1_dos_files[i];
    }
    return NULL;
}

int dm2_v1_dos_file_fp_matches_pc34(const char *name, size_t actual_size,
                                     const uint8_t sha256_actual[32]) {
    const dm2_v1_dos_file_fp_t *e = dm2_v1_dos_file_fp_lookup_pc34(name);
    if (!e) return 0;
    if (e->size_bytes != actual_size) return 0;
    if (!sha256_actual) return 0;
    return memcmp(e->sha256, sha256_actual, 32) == 0;
}
